const inp = $input.first().json;
const llmRaw = inp.output || inp.text || inp.response || inp.content || '';

let intent = { apiCode: null, params: {}, isComplex: false };
try {
  const m = llmRaw.match(/{[\s\S]*}/);
  if (m) intent = JSON.parse(m[0]);
} catch(e) {
  intent = { apiCode: null, params: {}, isComplex: true };
}

let username = 'demo';
try {
  const authHeader = $('Webhook AI Chat').first().json.headers?.authorization || '';
  const token = authHeader.replace(/^Bearer\s+/i, '').trim();
  if (token && token.split('.').length === 3) {
    const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString('utf-8'));
    username = payload.Username || payload.username || payload.sub || 'demo';
  }
} catch(e) {}

// Bắt luồng TẠO ĐƠN & ASK CLARIFICATION -> Né SQL Execute, đẩy qua nhánh Fallback/Bypass
if (intent.action_code) {
   // Nhánh này fallbackBody sẽ chứa kết quả JSON cho frontend ({action_code...})
   return [{ json: { isValid: false, fallbackBody: intent } }];
}

// Luồng truy vấn SQL (Như cũ)
if (intent.apiCode) intent.params = Object.assign({}, intent.params, { '@Username': username });

function toLocalISO(d) {
    const mm = (d.getMonth() + 1).toString().padStart(2, '0');
    return d.getFullYear() + '-' + mm + '-' + d.getDate().toString().padStart(2, '0');
}
const now = new Date();
const placeholders = { '[TODAY]': toLocalISO(now) }; // Giản lược cho ngắn gọn

const cleanParams = {};
for (const k of Object.keys(intent.params || {})) {
  let v = intent.params[k];
  if (v === '' || v === null || v === undefined || v === 'null') continue;
  let newK = k.startsWith('@') ? k : ('@' + k);
  if (typeof v === 'string' && placeholders[v]) v = placeholders[v];
  cleanParams[newK] = v;
}
intent.params = cleanParams;

const isValid = !!intent.apiCode && !intent.isComplex;
return [{ json: { apiCode: intent.apiCode, params: intent.params || {}, isComplex: !!intent.isComplex, username: username, isValid: isValid, _debug_llm: llmRaw.substring(0, 50) } }];

const k0 = $input.first()?.json || {};
const status = k0.status || 'success';
const count = k0.count || 0;
const data = k0.data || [];
const apiCode = $('Parse Intent & Auth').first().json.apiCode || '';

let message = '';
if (status === 'error') {
  message = k0.reply || k0.message || 'Co loi xay ra';
  return [{ json: { status: 'error', message: message, data: [], count: 0, apiCode: apiCode } }];
}

if (count === 0 || data.length === 0) {
  message = 'Khong tim thay du lieu phu hop.';
  return [{ json: { status: 'success', message: message, data: [], count: 0, apiCode: apiCode } }];
}

message = k0.reply || ('Tim thay ' + count + ' ket qua.');
return [{ json: {
  status: 'success',
  message: message,
  data: data,
  count: count,
  apiCode: apiCode
} }];
